124:     // 4. Route: GET /api/stream
125:     if (pathname === '/api/stream') {
126:       const tmdbId = searchParams.get('tmdbId');
127:       const type = searchParams.get('type');
128:       const season = searchParams.get('season');
129:       const episode = searchParams.get('episode');
130:       const server = searchParams.get('server') || 'secret';
131: 
132:       if (!tmdbId || !type) {
133:         return sendError(res, 400, 'Missing required query parameters: tmdbId and type are required');
134:       }
135: 
136:       if (type !== 'movie' && type !== 'tv') {
