138:       }
139: 
140:       if (type === 'tv' && (!season || !episode)) {
141:         return sendError(res, 400, "Missing required query parameters: season and episode are required for type 'tv'");
142:       }
143: 
144:       const streamResult = await resolver.resolveStream({
145:         tmdbId,
146:         type,
147:         season,
148:         episode,
149:         server,
150:       });
151: 
152:       if (!streamResult || !streamResult.playlist) {
153:         return sendError(res, 502, 'Stream resolution failed: no playlist found');
154:       }
155: 
156:       // Construct local proxy stream URL
157:       const host = req.headers.host || `127.0.0.1:${activePort}`;
158:       const encodedPlaylist = encodeURIComponent(streamResult.playlist);
159:       const streamUrl = `http://${host}/hls/proxy?url=${encodedPlaylist}`;
160: 
161:       // Build subtitles array
162:       const subtitles = [];
163:       if (Array.isArray(streamResult.captions)) {
164:         for (const cap of streamResult.captions) {
165:           subtitles.push({
166:             label: cap.language || cap.id || 'English',
167:             srclang: cap.id || 'en',
168:             src: `http://${host}/proxy/sub?url=${encodeURIComponent(cap.url)}`,
169:           });
170:         }
171:       }
172: 
173:       // Query external subtitles from subs.wing.st
174:       try {
175:         const extSubs = await resolver.fetchSubtitles({ tmdbId, type, season, episode });
176:         if (Array.isArray(extSubs)) {
177:           for (const s of extSubs) {
178:             if (s.url && !subtitles.some(existing => existing.src.includes(encodeURIComponent(s.url)))) {
179:               subtitles.push({
180:                 label: s.display || s.language || 'External',
181:                 srclang: s.language || 'en',
182:                 src: `http://${host}/proxy/sub?url=${encodeURIComponent(s.url)}`,
183:               });
184:             }
185:           }
186:         }
187:       } catch (_) {
188:         // External subtitles failure is non-fatal
189:       }
190: 
191:       return sendJson(res, 200, {
192:         success: true,
193:         streamUrl,
194:         originalUrl: streamResult.playlist,
195:         server: streamResult.server || server,
196:         subtitles,
197:       });
198:     }
199: 
200:     // 5. Route: GET /hls/proxy
201:     if (pathname === '/hls/proxy') {
202:       const targetUrl = searchParams.get('url');
203:       if (!targetUrl) {
204:         return sendError(res, 400, "Missing 'url' query parameter for HLS proxy");
205:       }
206:       return hlsProxy.handleHlsProxy(req, res, targetUrl, activePort);
207:     }
208: 
209:     // 6. Route: GET /proxy/sub
210:     if (pathname === '/proxy/sub') {
211:       const subUrl = searchParams.get('url');
212:       if (!subUrl) {
213:         return sendError(res, 400, "Missing 'url' query parameter for subtitle proxy");
214:       }
215: 
216:       try {
217:         const subResponse = await fetch(subUrl, {
218:           headers: {
219:             'User-Agent': 'Mozilla/5.0 (Web0S; SmartTV) AppleWebKit/537.36 Chrome/108.0.5359.211',
220:             'Origin': 'https://cinejoy.pk',
221:             'Referer': 'https://cinejoy.pk/',
222:           },
223:           signal: AbortSignal.timeout(10000)
224:         });
225: 
226:         if (!subResponse.ok) {
227:           return sendError(res, 502, `Failed to fetch remote subtitle: ${subResponse.status} ${subResponse.statusText}`);
228:         }
229: 
230:         const rawText = await subResponse.text();
231:         const vttContent = convertSrtToVtt(rawText);
232:         const buffer = Buffer.from(vttContent, 'utf8');
233: 
234:         res.writeHead(200, {
235:           ...CORS_HEADERS,
236:           'Content-Type': 'text/vtt; charset=utf-8',
237:           'Content-Length': buffer.length,
238:         });
239:         return res.end(buffer);
240:       } catch (err) {
241:         return sendError(res, 502, 'Failed to fetch subtitle', err.message);
242:       }
243:     }
244: 
245:     // 7. Route: 404 Fallthrough
246:     return sendError(res, 404, 'Endpoint Not Found', { path: pathname });
247:   } catch (err) {
248:     console.error(`[cinejoy-server] Error handling ${req.method} ${pathname}:`, err);
249:     return sendError(res, 500, 'Internal Server Error', err.message);
250:   }
