282: /**
283:  * Starts the HTTP server with port collision detection and fallback
284:  */
285: function startServer(initialPort = DEFAULT_PORT, host = DEFAULT_HOST) {
286:   return new Promise((resolve, reject) => {
287:     let currentPort = initialPort;
288:     let attempts = 0;
289: 
290:     function tryListen() {
291:       const server = http.createServer(requestHandler);
292: 
293:       server.on('error', (err) => {
294:         if (err.code === 'EADDRINUSE') {
295:           attempts++;
296:           console.warn(`[cinejoy-server] Port ${currentPort} in use, trying ${currentPort + 1}...`);
297:           currentPort++;
298:           if (attempts >= MAX_PORT_ATTEMPTS) {
299:             return reject(new Error(`Could not bind to any port in range ${initialPort}-${currentPort - 1}`));
300:           }
301:           setTimeout(tryListen, 50);
302:         } else {
303:           reject(err);
304:         }
305:       });
306: 
307:       server.on('listening', () => {
308:         activeServer = server;
309:         activePort = currentPort;
310:         writeStatusFiles(activePort);
311:         console.log(`[cinejoy-server] Server running on http://${host}:${activePort} (PID: ${process.pid})`);
312:         resolve({ server, port: activePort });
313:       });
314: 
315:       server.listen(currentPort, host);
316:     }
317: 
318:     tryListen();
319:   });
320: }
